from fractions import Fraction

# Train length L, speed v = L/t. Passing the pole takes t seconds.
# Passing the platform of length P takes 6t seconds: (L + P) / v = 6t  =>  L + P = 6L  =>  P = 5L.
# The platform is given as 5l, where l is the train's length. So L = P/5 = l.

evidence = []
ok = True
