        L = P / 5                  # from L + P = 6L  => L = P/5
        v = L / t
        time_platform = (L + P) / v
        if time_platform != 6 * t or L != l:
            ok = False
        evidence.append({"l": str(l), "t": str(t), "L": str(L), "platform_time": str(time_platform)})

if ok:
    result = {
        "final_answer": "l (the train's length equals l; platform = 5 times train length)",
        "evidence": {
            "derivation": "L + P = 6L => P = 5L; with P = 5l, L = l",
            "checks_passed": len(evidence),
            "samples": evidence[:3],
        },
    }
    print(json.dumps(result))
else:
